const items = $input.all();
const infoProyectos = items.filter(i => i.json._sheet === 'InfoProyectos').map(i => { const { _sheet, ...rest } = i.json; return rest; });
const backlog = items.filter(i => i.json._sheet === 'Backlog').map(i => { const { _sheet, ...rest } = i.json; return rest; });
return [{ json: { InfoProyectos: infoProyectos, Backlog: backlog } }];

function normalizarNombre(nombre) {
  return String(nombre || '')
    .normalize('NFD').replace(/\p{Diacritic}/gu, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

function calcularClave(row) {
  const pa = row['# PA'];
  if (pa !== null && pa !== undefined && String(pa).trim() !== '' && String(pa) !== '#N/A') {
    return 'pa:' + String(pa).trim();
  }
  return 'nombre:' + normalizarNombre(row['Nombre del Proyecto']);
}

function excelSerialToDate(serial) {
  return new Date(Date.UTC(1899, 11, 30) + serial * 86400000);
}

function parseFechaFin(v) {
  if (v instanceof Date) return v;
  if (typeof v === 'number') return excelSerialToDate(v);
  if (typeof v === 'string') {
    // 'Fecha fin' viene en formato MM/DD/YYYY (americano), confirmado con datos reales
    // (ej. '12/14/2026' solo es valido como mes/dia, nunca dia/mes).
    const m = v.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    if (m) {
      const mes = +m[1], dia = +m[2], anio = +m[3];
      if (mes < 1 || mes > 12 || dia < 1 || dia > 31) return null;
      const fecha = new Date(Date.UTC(anio, mes - 1, dia));
      if (fecha.getUTCMonth() !== mes - 1 || fecha.getUTCDate() !== dia) return null;
      return fecha;
    }
  }
  return null;
}

function calcularEstadoYDias(fechaFinRaw, hoyStr) {
  const fechaFin = parseFechaFin(fechaFinRaw);
  if (!fechaFin) return { dias: null, estado: null };
  const hoy = new Date(hoyStr + 'T00:00:00Z');
  const dias = Math.round((fechaFin - hoy) / 86400000);
  let estado;
  if (dias <= 0) estado = 'Contrato vencido';
  else if (dias <= 30) estado = 'Contrato vence en menos de 30dias';
  else if (dias < 60) estado = 'Contrato finaliza en menos de 60dias';
  else estado = 'Contrato vigente';
  return { dias, estado };
}


