function esVacia(row) {
  const pa = row['# PA'];
  const nombre = row['Nombre del Proyecto'];
  const paVacio = pa === null || pa === undefined || String(pa).trim() === '' || String(pa) === '#N/A';
  const nombreTexto = nombre === null || nombre === undefined ? '' : String(nombre).trim().toLowerCase();
  const nombreVacio = nombreTexto === '' || nombreTexto === 'n/a' || nombreTexto === '#n/a' || nombreTexto === 'na';
  return paVacio && nombreVacio;
}

const data = $json;
const infoSinVacias = (data.InfoProyectos || []).filter(row => !esVacia(row));
const backlogSinVacias = (data.Backlog || []).filter(row => !esVacia(row));
const filasVaciasDescartadas = (data.InfoProyectos || []).length - infoSinVacias.length
  + (data.Backlog || []).length - backlogSinVacias.length;
const fechaReferencia = new Date().toISOString().slice(0, 10);

function formatearFechaISO(fecha) {
  if (!fecha) return null;
  return fecha.toISOString().slice(0, 10);
}

const infoEnriquecido = infoSinVacias.map(row => {
  const { dias, estado } = calcularEstadoYDias(row['Fecha fin'], fechaReferencia);
  const fechaFinParsed = parseFechaFin(row['Fecha fin']);
  return {
    ...row,
    _clave: calcularClave(row),
    _dias_para_vencimiento: dias,
    _estado_contrato: estado,
    _fecha_fin_iso: formatearFechaISO(fechaFinParsed),
    _meses_transcurridos: row['Meses transcurridos'] !== null && row['Meses transcurridos'] !== undefined && String(row['Meses transcurridos']).trim() !== '' ? row['Meses transcurridos'] : calcularMesesTranscurridos(row['Fecha fin'], fechaReferencia),
    _executive_watchlist: row['Executive Watchlist'],
    _project_status: row['Project Status'],
  };
});

const backlogEnriquecido = backlogSinVacias.map(row => ({ ...row, _clave: calcularClave(row) }));

return [{ json: { InfoProyectos: infoEnriquecido, Backlog: backlogEnriquecido, fechaReferencia, filasVaciasDescartadas } }];

function esNumero(v) {
  if (v === null || v === undefined || v === '' || v === '#N/A') return false;
  return !isNaN(Number(v));
}

const data = $json;
const info = data.InfoProyectos || [];
const backlog = data.Backlog || [];
const errores = [];

if (info.length < 10) errores.push(`Muy pocos proyectos en Info Proyectos: ${info.length}`);
if (backlog.length < 10) errores.push(`Muy pocos proyectos en Backlog: ${backlog.length}`);

const clavesInfo = new Set(info.map(r => r._clave));
const sinCruce = backlog.filter(r => !clavesInfo.has(r._clave));
const cruzan = backlog.length - sinCruce.length;
const pctCruce = backlog.length ? cruzan / backlog.length : 0;
if (pctCruce < 0.95) {
  const ejemplos = sinCruce.slice(0, 15).map(r => `${r._clave} (${r['Nombre del Proyecto'] || 'sin nombre'})`).join('; ');
  errores.push(`Cruce entre hojas muy bajo: ${(pctCruce * 100).toFixed(1)}% (minimo 95%). Sin cruce (${sinCruce.length} de ${backlog.length}): ${ejemplos}`);
}

const conValorOf = info.filter(r => esNumero(r['Valor OF'])).length;
const pctValorOf = info.length ? conValorOf / info.length : 0;
if (pctValorOf < 0.5) errores.push(`Muy pocos Valor OF numericos: ${(pctValorOf * 100).toFixed(1)}% (minimo 50%)`);

return [{ json: { ...data, _validacion: { valido: errores.length === 0, errores } } }];

function cyrb53(str, seed = 0) {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507);
  h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507);
  h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}

function ordenarClaves(obj) {
  if (Array.isArray(obj)) return obj.map(ordenarClaves);
  if (obj && typeof obj === 'object') {
    return Object.keys(obj).sort().reduce((acc, k) => {
      acc[k] = ordenarClaves(obj[k]);
      return acc;
    }, {});
  }
  return obj;
}

const data = $json;
// Subir VERSION_ETL cada vez que cambie qué se extrae o cómo se calcula: así
// la misma planilla genera una carga nueva en vez de deduplicarse contra una
// carga hecha con la lógica anterior.
const VERSION_ETL = 3;
const payload = { version: VERSION_ETL, InfoProyectos: data.InfoProyectos, Backlog: data.Backlog };
const canonical = JSON.stringify(ordenarClaves(payload));
const hash = cyrb53(canonical);

return [{ json: { ...data, _hash: hash } }];

function sqlBool(v) {
  return v === true ? 'TRUE' : v === false ? 'FALSE' : 'NULL::boolean';
}

function parsearBooleano(v) {
  if (v === null || v === undefined || v === '') return null;
  const s = String(v).toLowerCase().trim();
  if (s === 'true' || s === '1' || s === 'sí' || s === 'si') return true;
  if (s === 'false' || s === '0' || s === 'no') return false;
  return null;
}


function parsearProjectStatus(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim().toLowerCase();
  if (s === 'red' || s === 'rojo') return 'Red';
  if (s === 'yellow' || s === 'amarillo') return 'Yellow';
  if (s === 'green' || s === 'verde') return 'Green';
  return null;
}

function sqlStr(v) {
  if (v === null || v === undefined || v === '' || v === '#N/A') return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
}
// En un VALUES sin montos, NULL sin tipo se infiere como text.
function sqlNum(v, ausente = 'NULL::numeric') {
  if (v === null || v === undefined || v === '' || v === '#N/A') return ausente;
  const n = Number(v);
  const LIMITE_MONTO = 100000000;
  if (!Number.isFinite(n) || Math.abs(n) > LIMITE_MONTO) return ausente;
  return String(n);
}
function sqlInt(v) {
  if (v === null || v === undefined) return 'NULL::integer';
  return String(Math.round(v));
}
function sqlDate(v) {
  if (v === null || v === undefined || v === '') return 'NULL::date';
  return "'" + v + "'::date";
}

// Drive puede entregar encabezados con espacios o saltos de linea.
function columnaBacklog(row, ...nombres) {
  const normalizar = nombre => nombre.replace(/\s+/g, ' ').trim().toUpperCase();
  const columnas = Object.keys(row);
  for (const nombre of nombres) {
    const clave = columnas.find(k => normalizar(k) === normalizar(nombre));
    if (clave !== undefined) return row[clave];
  }
  return null;
}

const data = $('Calcular Hash').item.json;
const info = data.InfoProyectos || [];
const backlog = data.Backlog || [];
const hash = data._hash;
const fechaReferencia = data.fechaReferencia;

const proyectosPorClave = new Map();
for (const row of info) proyectosPorClave.set(row._clave, row);
for (const row of backlog) if (!proyectosPorClave.has(row._clave)) proyectosPorClave.set(row._clave, row);

const backlogPorClave = new Map();
for (const row of backlog) if (!backlogPorClave.has(row._clave)) backlogPorClave.set(row._clave, row);
const backlogSinDuplicados = Array.from(backlogPorClave.values());

const proyectoValues = [];
for (const [clave, row] of proyectosPorClave) {
  proyectoValues.push(`(${sqlStr(clave)}, ${sqlStr(row['# PA'])}, ${sqlStr(row['Project ID'])}, ${sqlStr(row['# Opp.'])}, `
    + `${sqlStr(row['Nombre del Proyecto'])}, ${sqlStr(row['Cliente'])}, ${sqlStr(row['PM/Líder'])}, ${sqlStr(row['PM/Líder PSA'])}, `
    + `${sqlStr(row['Zona'])}, ${sqlStr(row['Pais'])}, ${sqlStr(row['Vendedor'])}, ${sqlStr(row['TSM'])}, `
    + `${sqlStr(row['Billing Type'])}, ${sqlStr(row['Billing Arrengement'])}, ${sqlStr(row['Estado'])}, `
    + `${sqlNum(row['Valor OF'])}, ${sqlNum(row['Valor OF Anterior'])}, ${sqlNum(row['ACUMULADO A HOY'])}, `
    + `${sqlNum(row['Consumido 2025'])}, ${sqlNum(row['Backlog 2026'])}, ${sqlDate(row._fecha_fin_iso)}, `
    + `${sqlInt(row._dias_para_vencimiento)}, ${sqlNum(row._meses_transcurridos)}, ${sqlStr(row._estado_contrato)}, ${sqlStr(row['ESTATUS'])}, `
    + `${sqlBool(parsearBooleano(row._executive_watchlist))}, ${sqlStr(parsearProjectStatus(row._project_status))})`);
}

const sqlProyectosUpsert = `proyectos_upsert AS (
  INSERT INTO proyecto (
    clave, num_pa, project_id, num_opp, nombre, cliente, pm_lider, pm_lider_psa,
    zona, pais, vendedor, tsm, billing_type, billing_arrangement, estado,
    valor_of, valor_of_anterior, acumulado_a_hoy, consumido_2025, backlog_2026, fecha_fin,
    dias_para_vencimiento, meses_transcurridos, estado_contrato, estatus,
    executive_watchlist, project_status, primera_carga_id, ultima_carga_id
  )
  SELECT v.*, (SELECT id FROM nueva_carga), (SELECT id FROM nueva_carga)
  FROM (VALUES
${proyectoValues.join(',\n')}
  ) AS v(
    clave, num_pa, project_id, num_opp, nombre, cliente, pm_lider, pm_lider_psa,
    zona, pais, vendedor, tsm, billing_type, billing_arrangement, estado,
    valor_of, valor_of_anterior, acumulado_a_hoy, consumido_2025, backlog_2026, fecha_fin,
    dias_para_vencimiento, meses_transcurridos, estado_contrato, estatus,
    executive_watchlist, project_status
  )
  ON CONFLICT (clave) DO UPDATE SET
    num_pa = EXCLUDED.num_pa, project_id = EXCLUDED.project_id, num_opp = EXCLUDED.num_opp,
    nombre = EXCLUDED.nombre, cliente = EXCLUDED.cliente, pm_lider = EXCLUDED.pm_lider, pm_lider_psa = EXCLUDED.pm_lider_psa,
    zona = EXCLUDED.zona, pais = EXCLUDED.pais, vendedor = EXCLUDED.vendedor, tsm = EXCLUDED.tsm,
    billing_type = EXCLUDED.billing_type, billing_arrangement = EXCLUDED.billing_arrangement, estado = EXCLUDED.estado,
    valor_of = EXCLUDED.valor_of, valor_of_anterior = EXCLUDED.valor_of_anterior, acumulado_a_hoy = EXCLUDED.acumulado_a_hoy,
    consumido_2025 = EXCLUDED.consumido_2025, backlog_2026 = EXCLUDED.backlog_2026, fecha_fin = EXCLUDED.fecha_fin,
    dias_para_vencimiento = EXCLUDED.dias_para_vencimiento, meses_transcurridos = EXCLUDED.meses_transcurridos,
    estado_contrato = EXCLUDED.estado_contrato, estatus = EXCLUDED.estatus,
    executive_watchlist = EXCLUDED.executive_watchlist, project_status = EXCLUDED.project_status,
    ultima_carga_id = (SELECT id FROM nueva_carga), actualizado_en = now()
  RETURNING id, clave
)`;

const MESES = [
  ['Enero', 1, 'Upside'], ['Febrero', 2, 'Upside_1'], ['Marzo', 3, 'Upside_2'],
  ['Abril', 4, 'Upside_3'], ['Mayo', 5, 'Upside_4'], ['Junio', 6, 'Upside_5'],
  ['Julio', 7, 'Upside_6'], ['Agosto', 8, 'Upside_7'], ['Septiembre', 9, 'Upside_8'],
  ['Octubre', 10, 'Upside_9'], ['Noviembre', 11, 'Upside_10'], ['Diciembre', 12, 'Upside_11'],
];

const revenueMesValues = [];
for (const row of backlogSinDuplicados) {
  for (const [mesNombre, mesNum, upsideCol] of MESES) {
    const commit = sqlNum(row[mesNombre], '0');
    const upside = sqlNum(row[upsideCol], '0');
    revenueMesValues.push(`(${sqlStr(row._clave)}, ${mesNum}, ${commit}, ${upside})`);
  }
}

const sqlRevenueMes = `revenue_mes_insert AS (
  INSERT INTO revenue_mes (carga_id, proyecto_id, mes, commit_usd, upside_usd)
  SELECT (SELECT id FROM nueva_carga), pu.id, v.mes, v.commit_usd, v.upside_usd
  FROM (VALUES
${revenueMesValues.join(',\n')}
  ) AS v(clave, mes, commit_usd, upside_usd)
  JOIN proyectos_upsert pu ON pu.clave = v.clave
  RETURNING proyecto_id, mes, commit_usd, upside_usd
)`;

const revenueAnualValues = backlogSinDuplicados.map(row => {
  // FIX: valor_of debe venir de BackLog NOLA (row['Valor OF']), NO de Info Proyectos
  const valorOf = sqlNum(row['Valor OF']);
  return `(${sqlStr(row._clave)}, ${valorOf}, ${sqlNum(row['Acum 2025'])}, ${sqlNum(columnaBacklog(row, 'Backlog 2026', 'Backlog'))}, ${sqlNum(columnaBacklog(row, 'TOTAL EJECUTADO ACUMULADO 2025-2026 (COPIAR)', 'TOTAL EJECUTADO ACUMULADO'))})`;
});

const sqlRevenueAnual = `revenue_anual_insert AS (
  INSERT INTO revenue_anual (carga_id, proyecto_id, valor_of, acum_2025, backlog, total_ejecutado_acumulado)
  SELECT (SELECT id FROM nueva_carga), pu.id, v.valor_of, v.acum_2025, v.backlog, v.total_ejecutado
  FROM (VALUES
${revenueAnualValues.join(',\n')}
  ) AS v(clave, valor_of, acum_2025, backlog, total_ejecutado)
  JOIN proyectos_upsert pu ON pu.clave = v.clave
  RETURNING 1
)`;

const sqlMovimiento = `movimiento_insert AS (
  INSERT INTO movimiento (carga_id, carga_previa_id, proyecto_id, mes, tipo, monto, commit_anterior, commit_nuevo, upside_anterior, upside_nuevo)
  SELECT
    (SELECT id FROM nueva_carga), (SELECT id FROM carga_previa),
    n.proyecto_id, n.mes,
    CASE WHEN n.commit_usd > COALESCE(a.commit_usd, 0) THEN 'upside_a_commit' ELSE 'commit_a_upside' END,
    abs(n.commit_usd - COALESCE(a.commit_usd, 0)),
    a.commit_usd, n.commit_usd, a.upside_usd, n.upside_usd
  FROM revenue_mes_insert n
  LEFT JOIN revenue_mes a
    ON a.carga_id = (SELECT id FROM carga_previa) AND a.proyecto_id = n.proyecto_id AND a.mes = n.mes
  WHERE (SELECT id FROM carga_previa) IS NOT NULL
    AND abs(n.commit_usd - COALESCE(a.commit_usd, 0)) >= 1.0
  RETURNING 1
)`;

const sql = `BEGIN;
WITH
nueva_carga AS (
  INSERT INTO carga (archivo_nombre, datos_hash, fecha_referencia, filas_info, filas_backlog)
  VALUES ('CLOUD FORECAST GENERAL - NOLA FY26', ${sqlStr(hash)}, ${sqlStr(fechaReferencia)}, ${info.length}, ${backlog.length})
  RETURNING id
),
carga_previa AS (
  SELECT id FROM carga WHERE id < (SELECT id FROM nueva_carga) ORDER BY id DESC LIMIT 1
),
${sqlProyectosUpsert},
${sqlRevenueMes},
${sqlRevenueAnual},
${sqlMovimiento}
SELECT
  (SELECT id FROM nueva_carga) AS carga_id,
  (SELECT count(*) FROM proyectos_upsert) AS proyectos,
  (SELECT count(*) FROM revenue_mes_insert) AS filas_revenue,
  (SELECT count(*) FROM movimiento_insert) AS movimientos;
COMMIT;`;

return [{ json: { sql } }];
